/// <summary>
/// Lookup of METPurchaseOrderBasis
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormControlEventHandler(formControlStr(TAMRebateParameters, METVendorRebateDeals_METPurchaseOrderBasis), FormControlEventType::Lookup)]
public static void METVendorRebateDeals_METPurchaseOrderBasis_OnLookup(FormControl sender, FormControlEventArgs e)
{
    TAMRebateParameters tamRebateParameters = sender.formRun().dataSource(formDataSourceStr(TAMRebateParameters, TAMRebateParameters)).cursor();

    Query query = new Query();
    QueryBuildDataSource queryBuildDataSource;
    QueryBuildRange queryBuildRange;

    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(GUPPriceComponentCodePriceAttributeGroupCombination), sender);

    sysTableLookup.addLookupField(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, Name));
    sysTableLookup.addLookupField(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderGroupAll));
    sysTableLookup.addLookupField(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderPriceAttributeGroupName));

    queryBuildDataSource = query.addDataSource(tableNum(GUPPriceComponentCodePriceAttributeGroupCombination));
    queryBuildDataSource.addRange(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination,PriceComponentCodeName)).value(tamRebateParameters.METPriceComponentCode);

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup(); 

    FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
    //cancel super() to prevent error.
    if (ce)
    {
        ce.CancelSuperCall();
    }

}

