/// <summary>
/// Enable disable form control
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormEventHandler(formStr(TAMRebateParameters), FormEventType::Activated)]
public static void TAMRebateParameters_OnActivated(xFormRun sender, FormEventArgs e)
{
    TAMRebateParameters tamRebateParameters = sender.dataSource(formDataSourceStr(TAMRebateParameters, TAMRebateParameters)).cursor();

    FormControl purchOrderBasis = sender.design().controlName(formControlStr(TAMRebateParameters, METVendorRebateDeals_METPurchaseOrderBasis)) as FormControl;
    FormControl salesOrderBasis = sender.design().controlName(formControlStr(TAMRebateParameters, METVendorRebateDeals_METSalesOrderBasis)) as FormControl;
    if(tamRebateParameters.METPriceComponentCode)
    {
        purchOrderBasis.enabled(true);
        salesOrderBasis.enabled(true);
    }
    else
    {
        purchOrderBasis.enabled(false);
        salesOrderBasis.enabled(false);
    }
}

/// <summary>
/// Enable disable form control
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>    
[FormControlEventHandler(formControlStr(TAMRebateParameters, METVendorRebateDeals_METPriceComponentCode), FormControlEventType::Modified)]
public static void METVendorRebateDeals_METPriceComponentCode_OnModified(FormControl sender, FormControlEventArgs e)
{ 
    TAMRebateParameters tamRebateParameters = sender.formRun().dataSource(formdatasourcestr(TAMRebateParameters, TAMRebateParameters)).cursor() as TAMRebateParameters;

    if(tamRebateParameters.METPriceComponentCode)
    {
        sender.formRun().design().controlName(formControlStr(TAMRebateParameters, METVendorRebateDeals_METPurchaseOrderBasis)).enabled(true);

        sender.formRun().design().controlName(formControlStr(TAMRebateParameters, METVendorRebateDeals_METSalesOrderBasis)).enabled(true);
    }
    else
    {
        tamRebateParameters.METPurchaseOrderBasis = '';
        tamRebateParameters.METSalesOrderBasis = '';
        sender.formRun().design().controlName(formControlStr(TAMRebateParameters, METVendorRebateDeals_METPurchaseOrderBasis)).enabled(false);
        sender.formRun().design().controlName(formControlStr(TAMRebateParameters, METVendorRebateDeals_METSalesOrderBasis)).enabled(false);
    }
}
